d:#fff0ef;color:var(--bad)!important}.pill.warn{background:#fff6dd;color:var(--warn)!important}.empty{padding:10px;border:1px dashed #c7ccd2;border-radius:9px;color:var(--muted);font-size:10px;text-align:center}.cards{display:grid;grid-template-columns:1fr 1fr;gap:7px}.card{padding:9px;border:1px solid var(--line);border-radius:9px;background:#fafbfc}.card b{display:block;font-size:20px}.card span{font-size:9px;text-transform:uppercase;color:var(--muted)}.asset-detail{display:grid;gap:7px}.detail-row{display:flex;justify-content:space-between;gap:10px;font-size:10px;border-bottom:1px solid #eceff1;padding-bottom:5px}.detail-row span{color:var(--muted)}.detail-row strong{text-align:right}.alert{padding:8px;border-radius:8px;font-size:10px;line-height:1.4}.alert.warn{border:1px solid #efd38a;background:#fff9e8;color:#6e5400}.alert.bad{border:1px solid #efb5af;background:#fff2f0;color:#8e211b}.alert.good{border:1px solid #aed8b8;background:#f1fbf3;color:#125f39}.agent-box{border:1px solid #efc8bc;border-radius:10px;padding:9px;background:linear-gradient(145deg,#fff,#fff8f5)}.agent-output{margin-top:7px;padding:8px;border-radius:8px;background:#f5f5f3;white-space:pre-wrap;font-size:10px;line-height:1.45;max-height:220px;overflow:auto}.quick{display:flex;flex-wrap:wrap;gap:5px;margin-top:6px}.quick button{border:1px solid #ead5ce;border-radius:999px;background:#fff;padding:5px 7px;font-size:9px}.legacy{position:absolute;border:2px dashed #b66d4d;background:rgba(246,223,212,.45);color:#7a321d;display:flex;align-items:center;justify-content:center;text-align:center;padding:4px;font-size:9px;font-weight:800}.legacy::after{content:'LEGACY';position:absolute;top:2px;right:2px;font-size:6px;background:#7a321d;color:#fff;padding:1px 3px;border-radius:3px}.readonly{padding:7px 11px;background:#fff5d8;color:#6a5100;font-size:11px;border-bottom:1px solid #e8cf86}.hidden{display:none!important}.modal{position:fixed;inset:0;z-index:200000;background:rgba(0,0,0,.48);display:none;place-items:center;padding:20px}.modal.open{display:grid}.modal-box{width:min(560px,100%);max-height:90vh;overflow:auto;background:#fff;border-radius:15px;padding:16px}.modal-head{display:flex;align-items:center;justify-content:space-between;margin-bottom:10px}.modal-head h3{margin:0}.modal-head button{border:0;background:none;font-size:22px}@media(max-width:1150px){.workspace{grid-template-columns:245px minmax(430px,1fr) 300px}}@media(max-width:900px){.workspace{grid-template-columns:220px 1fr}.inspect{position:fixed;right:0;top:60px;bottom:0;width:300px;z-index:50;box-shadow:-10px 0 30px rgba(0,0,0,.12)}}
