<script>
(()=>{'use strict';
const CAN_EDIT=<?= $canEdit?'true':'false' ?>,CAN_EQUIPMENT=<?= $canEquipment?'true':'false' ?>,CAN_EQUIPMENT_EDIT=<?= $canEquipmentEdit?'true':'false' ?>,CAN_AGENT=<?= $canAgent?'true':'false' ?>,CSRF=<?= json_encode($csrf,JSON_HEX_TAG|JSON_HEX_AMP|JSON_HEX_APOS|JSON_HEX_QUOT|JSON_THROW_ON_ERROR) ?>;
const $=id=>document.getElementById(id),stage=$('stage'),holder=$('holder');
let plans=[],activePlanId='',planW=50,planH=34,scale=24,zoom=1,zCounter=100,selected=null,selectedKind='',equipment=[],legacyItems=[],dirty=false;
const equipmentLegacyTypes=new Set(['pizza-oven','dough-mixer','prep-table','pizza','salad','server','walkin','keg','wine','shelving','sink3','handsink','dish','batch-freezer','blast-freezer','gelato','pos']);
const defs={table:{label:'4-TOP',cls:'table',wIn:48,hIn:36,seats:4,zone:'dining'},chair:{label:'',cls:'chair',wIn:20,hIn:20,seats:1,zone:'dining'},bar:{label:'BAR',cls:'bar',wIn:180,hIn:72,seats:12,zone:'bar'},host:{label:'HOST',cls:'host',wIn:36,hIn:24,seats:0,zone:'none'},zone:{label:'ZONE',cls:'zone',wIn:120,hIn:96,seats:0,zone:'none'},aisle:{label:'AISLE',cls:'aisle',wIn:48,hIn:120,seats:0,zone:'none'},wall:{label:'',cls:'wall',wIn:120,hIn:6,seats:0,zone:'none'},door:{label:'DOOR',cls:'door',wIn:36,hIn:6,seats:0,zone:'none'}};
const fallbackFootprints={oven:[60,48],mixer:[30,36],refrigeration:[72,34],gelato_machine:[36,30],dishwasher:[30,30],sink:[36,24],utensil:[18,18],smallware:[18,18],bar_equipment:[36,24],pos:[24,18],other:[36,30]};
function setStatus(text,bad=false){$('status').textContent=text;$('status').style.color=bad?'#ffb4ad':'#c5cad0';clearTimeout(setStatus.t);setStatus.t=setTimeout(()=>{$('status').textContent='Ready';$('status').style.color='#c5cad0'},2200)}
function pxFromIn(v){return (Number(v)||0)/12*scale}function inFromPx(v){return (Number(v)||0)/scale*12}function snap(v){const step=scale/2;return Math.round(v/step)*step}function fmtIn(v){const n=Math.round(Number(v)||0),f=Math.floor(n/12),i=n%12;return `${f}' ${i}"`}function money(v){return '$'+Math.round(Number(v)||0).toLocaleString()}
async function api(url,options={}){const o={...options,headers:{Accept:'application/json',...(options.headers||{})}};if(o.method&&o.method!=='GET')o.headers['X-CSRF-Token']=CSRF;if(o.body&&typeof o.body!=='string'){o.headers['Content-Type']='application/json';o.body=JSON.stringify(o.body)}const r=await fetch(url,o);let d;try{d=await r.json()}catch{throw new Error(`Invalid server response (${r.status}).`)}if(!r.ok||d.ok===false)throw new Error(d.message||`Request failed (${r.status}).`);return d}
function updateCanvas(){const w=planW*scale,h=planH*scale;stage.style.width=w+'px';stage.style.height=h+'px';stage.style.transform=`scale(${zoom})`;holder.style.width=(w*zoom)+'px';holder.style.height=(h*zoom)+'px';document.documentElement.style.setProperty('--grid',(scale/2)+'px');$('sqft').value=(planW*planH).toLocaleString(undefined,{maximumFractionDigits:1})}
function structuralData(el){return {id:el.dataset.id,type:el.dataset.type,label:el.querySelector('.label').textContent,xPx:parseFloat(el.style.left)||0,yPx:parseFloat(el.style.top)||0,wPx:parseFloat(el.style.width)||0,hPx:parseFloat(el.style.height)||0,r:Number(el.dataset.rotation)||0,z:Number(el.style.zIndex)||1,seats:Number(el.dataset.seats)||0,seatZone:el.dataset.seatZone||'none'}}
function makeStructure(type,x=48,y=48,data={}){const d=defs[type]||defs.zone,el=document.createElement('div');el.className='structure '+d.cls;el.dataset.id=data.id||`structure-${Date.now().toString(36)}-${Math.random().toString(36).slice(2,7)}`;el.dataset.type=type;el.dataset.rotation=data.r||0;el.dataset.seats=data.seats??d.seats;el.dataset.seatZone=data.seatZone??d.zone;el.style.left=(data.xPx??snap(x))+'px';el.style.top=(data.yPx??snap(y))+'px';el.style.width=(data.wPx??pxFromIn(d.wIn))+'px';el.style.height=(data.hPx??pxFromIn(d.hIn))+'px';el.style.transform=`rotate(${el.dataset.rotation}deg)`;el.style.zIndex=data.z||++zCounter;el.innerHTML=`<span class="label"></span><span class="dim"></span><span class="resize"></span>`;el.querySelector('.label').textContent=data.label??d.label;stage.appendChild(el);bindStructure(el);updateDim(el);return el}
function updateDim(el){el.querySelector('.dim').textContent=`${fmtIn(inFromPx(parseFloat(el.style.width)))} × ${fmtIn(inFromPx(parseFloat(el.style.height)))}`}
function bindStructure(el){el.addEventListener('pointerdown',e=>{if(!CAN_EDIT||e.button!==0||e.target.classList.contains('resize'))return;selectObject(el,'structure');const sx=e.clientX,sy=e.clientY,l=parseFloat(el.style.left),t=parseFloat(el.style.top);el.setPointerCapture(e.pointerId);const mv=ev=>{el.style.left=Math.max(0,snap(l+(ev.clientX-sx)/zoom))+'px';el.style.top=Math.max(0,snap(t+(ev.clientY-sy)/zoom))+'px';dirty=true;recalc()};const up=ev=>{el.releasePointerCapture(ev.pointerId);el.removeEventListener('pointermove',mv);el.removeEventListener('pointerup',up)};el.addEventListener('pointermove',mv);el.addEventListener('pointerup',up)});const h=el.querySelector('.resize');h.addEventListener('pointerdown',e=>{if(!CAN_EDIT)return;e.stopPropagation();selectObject(el,'structure');const sx=e.clientX,sy=e.clientY,w=parseFloat(el.style.width),ht=parseFloat(el.style.height);h.setPointerCapture(e.pointerId);const mv=ev=>{el.style.width=Math.max(scale/2,snap(w+(ev.clientX-sx)/zoom))+'px';el.style.height=Math.max(scale/2,snap(ht+(ev.clientY-sy)/zoom))+'px';updateDim(el);dirty=true;recalc()};const up=ev=>{h.releasePointerCapture(ev.pointerId);h.removeEventListener('pointermove',mv);h.removeEventListener('pointerup',up)};h.addEventListener('pointermove',mv);h.addEventListener('pointerup',up)})}
function footprint(asset){const fallback=fallbackFootprints[asset.assetType]||fallbackFootprints.other;return [asset.widthInches||fallback[0],asset.depthInches||fallback[1],!asset.widthInches||!asset.depthInches]}
function makeEquipment(asset){const [wIn,hIn,estimated]=footprint(asset),el=document.createElement('div');el.className=`equipment type-${asset.assetType} status-${asset.operationalStatus}${asset.locked?' locked':''}`;el.dataset.assetId=asset.id;el.dataset.rotation=asset.rotationDeg||0;el.style.left=((asset.xFt??1)*scale)+'px';el.style.top=((asset.yFt??1)*scale)+'px';el.style.width=pxFromIn(wIn)+'px';el.style.height=pxFromIn(hIn)+'px';el.style.transform=`rotate(${asset.rotationDeg||0}deg)`;el.style.zIndex=asset.zIndex||10;const due=asset.maintenanceRequired&&asset.nextServiceOn&&new Date(asset.nextServiceOn)<=new Date(Date.now()+30*86400000);el.innerHTML=`<span class="label"></span><span class="asset-badge">ASSET</span>${due?'<span class="service-badge">SERVICE</span>':''}<span class="dim"></span>${CAN_EQUIPMENT_EDIT?'<span class="resize"></span>':''}`;el.querySelector('.label').textContent=asset.name;el.querySelector('.dim').textContent=`${fmtIn(wIn)} × ${fmtIn(hIn)}${estimated?' est.':''}`;stage.appendChild(el);bindEquipment(el);return el}
function assetById(id){return equipment.find(a=>a.id===id)}
function bindEquipment(el){el.addEventListener('click',e=>{e.stopPropagation();selectObject(el,'equipment')});el.addEventListener('dblclick',()=>openAsset(assetById(el.dataset.assetId)));el.addEventListener('pointerdown',e=>{const asset=assetById(el.dataset.assetId);if(!CAN_EDIT||asset?.locked||e.button!==0||e.target.classList.contains('resize'))return;selectObject(el,'equipment');const sx=e.clientX,sy=e.clientY,l=parseFloat(el.style.left),t=parseFloat(el.style.top);el.setPointerCapture(e.pointerId);const mv=ev=>{el.style.left=Math.max(0,snap(l+(ev.clientX-sx)/zoom))+'px';el.style.top=Math.max(0,snap(t+(ev.clientY-sy)/zoom))+'px'};const up=async ev=>{el.releasePointerCapture(ev.pointerId);el.removeEventListener('pointermove',mv);el.removeEventListener('pointerup',up);try{await savePlacement(asset,'move',parseFloat(el.style.left)/scale,parseFloat(el.style.top)/scale,Number(el.dataset.rotation)||0,Number(el.style.zIndex)||10)}catch(err){setStatus(err.message,true);await loadPlacements()}};el.addEventListener('pointermove',mv);el.addEventListener('pointerup',up)});const handle=el.querySelector('.resize');if(handle)handle.addEventListener('pointerdown',e=>{const asset=assetById(el.dataset.assetId);if(!CAN_EQUIPMENT_EDIT||asset?.locked)return;e.stopPropagation();selectObject(el,'equipment');const sx=e.clientX,sy=e.clientY,w=parseFloat(el.style.width),h=parseFloat(el.style.height);handle.setPointerCapture(e.pointerId);const mv=ev=>{el.style.width=Math.max(scale/2,snap(w+(ev.clientX-sx)/zoom))+'px';el.style.height=Math.max(scale/2,snap(h+(ev.clientY-sy)/zoom))+'px';el.querySelector('.dim').textContent=`${fmtIn(inFromPx(parseFloat(el.style.width)))} × ${fmtIn(inFromPx(parseFloat(el.style.height)))}`};const up=async ev=>{handle.releasePointerCapture(ev.pointerId);handle.removeEventListener('pointermove',mv);handle.removeEventListener('pointerup',up);try{const d=await api('api/equipment-placement.php',{method:'POST',body:{action:'resize',assetId:asset.id,widthInches:inFromPx(parseFloat(el.style.width)),depthInches:inFromPx(parseFloat(el.style.height))}});Object.assign(asset,d.asset);renderCatalog();renderEquipmentInspector(asset);setStatus('Equipment dimensions saved to catalog')}catch(err){setStatus(err.message,true);await loadPlacements()}};handle.addEventListener('pointermove',mv);handle.addEventListener('pointerup',up)})}
function clearStage(){stage.querySelectorAll('.structure,.equipment,.legacy').forEach(el=>el.remove());selected=null;selectedKind='';renderSelection()}
function selectObject(el,kind){document.querySelectorAll('.selected').forEach(n=>n.classList.remove('selected'));selected=el;selectedKind=kind;if(el)el.classList.add('selected');renderSelection()}
function renderSelection(){$('selectionEmpty').classList.toggle('hidden',!!selected);$('structureInspector').classList.toggle('hidden',selectedKind!=='structure');$('equipmentInspector').classList.toggle('hidden',selectedKind!=='equipment');if(selectedKind==='structure'&&selected){$('sLabel').value=selected.querySelector('.label').textContent;$('sW').value=(parseFloat(selected.style.width)/scale).toFixed(2);$('sH').value=(parseFloat(selected.style.height)/scale).toFixed(2);$('sSeats').value=selected.dataset.seats;$('sSeatZone').value=selected.dataset.seatZone}else if(selectedKind==='equipment'&&selected){renderEquipmentInspector(assetById(selected.dataset.assetId))}}
function renderEquipmentInspector(asset){if(!asset)return;const age=asset.manufactureYear?Math.max(0,new Date().getFullYear()-asset.manufactureYear)+' years':'—',due=asset.nextServiceOn||'Not scheduled',foot=footprint(asset);$('assetDetail').innerHTML=`<div class="detail-row"><span>Asset</span><strong>${escapeHtml(asset.name)}</strong></div><div class="detail-row"><span>Type</span><strong>${escapeHtml(asset.assetType)}</strong></div><div class="detail-row"><span>Brand / model</span><strong>${escapeHtml([asset.brand,asset.model].filter(Boolean).join(' ')||'—')}</strong></div><div class="detail-row"><span>Status</span><strong>${escapeHtml(asset.operationalStatus.replaceAll('_',' '))}</strong></div><div class="detail-row"><span>Criticality</span><strong>${escapeHtml(asset.criticality)}</strong></div><div class="detail-row"><span>Location</span><strong>${escapeHtml(asset.locationName||'—')}</strong></div><div class="detail-row"><span>Age</span><strong>${age}</strong></div><div class="detail-row"><span>Footprint</span><strong>${fmtIn(foot[0])} × ${fmtIn(foot[1])}${foot[2]?' (visual estimate)':''}</strong></div><div class="detail-row"><span>Next service</span><strong>${escapeHtml(due)}</strong></div><div class="detail-row"><span>Plan position</span><strong>${Number(asset.xFt||0).toFixed(1)}′, ${Number(asset.yFt||0).toFixed(1)}′ · ${Number(asset.rotationDeg||0)}°</strong></div>`;$('lockAssetBtn').textContent=asset.locked?'Unlock Position':'Lock Position'}
function escapeHtml(v){return String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}
function structureItems(){return [...stage.querySelectorAll('.structure')].map(structuralData)}
function loadStructure(data){stage.querySelectorAll('.structure,.legacy').forEach(e=>e.remove());legacyItems=[];const items=Array.isArray(data?.items)?data.items:[];items.forEach(item=>{if(equipmentLegacyTypes.has(item.type)){legacyItems.push(item);const el=document.createElement('div');el.className='legacy';el.style.left=(item.xPx||0)+'px';el.style.top=(item.yPx||0)+'px';el.style.width=(item.wPx||60)+'px';el.style.height=(item.hPx||40)+'px';el.textContent=item.label||item.type;stage.appendChild(el);return}if(defs[item.type])makeStructure(item.type,item.xPx,item.yPx,item)});if(legacyItems.length)setStatus(`${legacyItems.length} legacy equipment block(s) shown as ghosts`,true)}
async function listPlans(){const d=await api('api/floor-plans.php',{method:'GET'});plans=d.plans||[];$('planSelect').innerHTML='<option value="">Choose saved plan…</option>'+plans.map(p=>`<option value="${escapeHtml(p.id)}">${escapeHtml(p.name)} · v${p.version}</option>`).join('');const requested=new URLSearchParams(location.search).get('plan');if(!activePlanId&&requested&&plans.some(p=>p.id===requested))activePlanId=requested;if(!activePlanId&&plans.length)activePlanId=(plans.find(p=>p.isDefault)||plans[0]).id;if(activePlanId){$('planSelect').value=activePlanId;await loadPlan(activePlanId)}else{newBlankPlan(false)}}
async function loadPlan(id){const d=await api('api/floor-plans.php?id='+encodeURIComponent(id),{method:'GET'});const p=d.plan;activePlanId=p.id;$('planName').value=p.name;planW=Number(p.data?.planWft??p.widthFt??50);planH=Number(p.data?.planHft??p.depthFt??34);scale=Number(p.data?.scale??p.scale??24);$('planW').value=planW;$('planH').value=planH;$('scale').value=scale;updateCanvas();clearStage();loadStructure(p.data||{});await loadPlacements();dirty=false;history.replaceState(null,'','?plan='+encodeURIComponent(activePlanId));setStatus('Plan loaded')}
async function loadPlacements(){stage.querySelectorAll('.equipment').forEach(e=>e.remove());if(!activePlanId||!CAN_EQUIPMENT){equipment=[];renderCatalog();recalc();return}try{const d=await api('api/equipment-placement.php?plan='+encodeURIComponent(activePlanId),{method:'GET'});equipment=[...(d.placed||[]),...(d.unplaced||[]),...(d.otherPlans||[])];(d.placed||[]).forEach(makeEquipment);renderCatalog();recalc()}catch(err){equipment=[];renderCatalog();setStatus(err.message,true);recalc()}}
function renderCatalog(){if(!CAN_EQUIPMENT)return;const q=$('assetSearch').value.trim().toLowerCase();const match=a=>!q||[a.name,a.assetType,a.brand,a.model,a.locationName].join(' ').toLowerCase().includes(q);const card=(a,placed)=>`<div class="asset-card" draggable="${!placed&&CAN_EDIT?'true':'false'}" data-asset-card="${escapeHtml(a.id)}"><div class="meta"><strong>${escapeHtml(a.name)}</strong><span class="pill ${a.operationalStatus==='out_of_service'?'bad':a.operationalStatus==='maintenance'?'warn':''}">${escapeHtml(a.operationalStatus.replaceAll('_',' '))}</span></div><span>${escapeHtml([a.assetType,a.brand,a.model].filter(Boolean).join(' · '))}</span>${placed?`<span>${Number(a.xFt||0).toFixed(1)}′ × ${Number(a.yFt||0).toFixed(1)}′</span>`:'<span>Drag onto plan</span>'}</div>`;const placed=equipment.filter(a=>a.floorPlanId===activePlanId&&match(a)),unplaced=equipment.filter(a=>!a.floorPlanId&&match(a));$('unplacedAssets').innerHTML=unplaced.length?unplaced.map(a=>card(a,false)).join(''):'<div class="empty">No unplaced equipment matches.</div>';$('placedAssets').innerHTML=placed.length?placed.map(a=>card(a,true)).join(''):'<div class="empty">No equipment placed yet.</div>';document.querySelectorAll('[data-asset-card]').forEach(el=>{const id=el.dataset.assetCard;el.addEventListener('dragstart',e=>e.dataTransfer.setData('application/x-equipment-asset',id));el.addEventListener('click',()=>{const asset=assetById(id);if(asset?.floorPlanId===activePlanId){const node=stage.querySelector(`[data-asset-id="${CSS.escape(id)}"]`);if(node)selectObject(node,'equipment')}})})}
async function savePlacement(asset,action,xFt,yFt,rotation,z){const d=await api('api/equipment-placement.php',{method:'POST',body:{action,assetId:asset.id,planId:activePlanId,xFt,yFt,rotationDeg:rotation,zIndex:z}});Object.assign(asset,d.asset);renderCatalog();recalc();setStatus(action==='place'?'Equipment placed':'Equipment position saved');return d.asset}
async function placeAsset(id,xFt,yFt){if(!activePlanId){setStatus('Save the floor plan before placing equipment.',true);return}const asset=assetById(id);if(!asset)return;const d=await savePlacement(asset,'place',Math.max(0,xFt),Math.max(0,yFt),0,++zCounter);makeEquipment(d);renderCatalog();recalc();const node=stage.querySelector(`[data-asset-id="${CSS.escape(id)}"]`);if(node)selectObject(node,'equipment')}
function openAsset(asset){if(!asset)return;location.href='equipment-detail.php?id='+encodeURIComponent(asset.id)+'&return='+encodeURIComponent('floor-planner-ops.php?plan='+activePlanId)}
async function savePlan(){if(!CAN_EDIT)return;const name=$('planName').value.trim();if(!name){setStatus('Plan name is required.',true);return}planW=Math.max(10,Number($('planW').value)||50);planH=Math.max(10,Number($('planH').value)||34);scale=Math.max(8,Number($('scale').value)||24);const data={version:4,planWft:planW,planHft:planH,scale,items:structureItems(),canonicalEquipment:true};try{const d=await api('api/floor-plans.php',{method:'POST',body:{action:'save',plan:{id:activePlanId,name,data}}});activePlanId=d.plan.id;dirty=false;await listPlans();$('planSelect').value=activePlanId;setStatus('Layout saved to database')}catch(err){setStatus(err.message,true)}}
function newBlankPlan(confirmFirst=true){if(confirmFirst&&dirty&&!confirm('Discard unsaved structural layout changes?'))return;activePlanId='';$('planName').value='New Pizzeria Layout';planW=50;planH=34;scale=24;$('planW').value=50;$('planH').value=34;$('scale').value=24;updateCanvas();clearStage();equipment=[];renderCatalog();makeStructure('bar',21*scale,18*scale,{wPx:15*scale,hPx:7*scale,seats:18,seatZone:'bar'});dirty=true;recalc();history.replaceState(null,'',location.pathname);setStatus('New unsaved plan')}
function applyStructureInspector(){if(selectedKind!=='structure'||!selected||!CAN_EDIT)return;selected.querySelector('.label').textContent=$('sLabel').value;selected.style.width=Math.max(scale/2,(Number($('sW').value)||.5)*scale)+'px';selected.style.height=Math.max(scale/2,(Number($('sH').value)||.5)*scale)+'px';selected.dataset.seats=Math.max(0,Number($('sSeats').value)||0);selected.dataset.seatZone=$('sSeatZone').value;updateDim(selected);dirty=true;recalc()}
function recalc(){const seats=[...stage.querySelectorAll('.structure')].reduce((sum,e)=>sum+(Number(e.dataset.seats)||0),0),placed=equipment.filter(a=>a.floorPlanId===activePlanId),now=new Date(),soon=new Date(Date.now()+30*86400000),due=placed.filter(a=>a.maintenanceRequired&&a.nextServiceOn&&new Date(a.nextServiceOn)<=soon).length,out=placed.filter(a=>a.operationalStatus==='out_of_service').length;$('seatCount').textContent=seats;$('equipmentCount').textContent=placed.length;$('dueCount').textContent=due;$('outCount').textContent=out;const warnings=[];if(!activePlanId)warnings.push('Save this plan before placing canonical equipment assets.');if(legacyItems.length)warnings.push(`${legacyItems.length} legacy equipment block(s) are still stored in the old plan JSON. Recreate those assets in the Equipment Catalog, place them here, then delete the legacy blocks from the original planner.`);if(out)warnings.push(`${out} placed asset(s) are marked out of service.`);if(due)warnings.push(`${due} placed asset(s) have maintenance overdue or due within 30 days.`);const box=$('checks');box.className='alert '+(warnings.length?'warn':'good');box.innerHTML=warnings.length?warnings.map(escapeHtml).join('<br>'):'Canonical equipment placement and current maintenance status look clear.'}
async function askAgent(message){if(!CAN_AGENT||!message.trim())return;try{$('agentOutput').textContent='Thinking…';const d=await api('api/agent-brain.php',{method:'POST',body:{action:'ask',message:message.trim()}});$('agentOutput').textContent=d.answer||'No answer returned.'}catch(err){$('agentOutput').textContent=err.message}}
function bind(){
$('backBtn').onclick=()=>location.href='index.php';$('equipmentCatalogBtn').onclick=()=>location.href='equipment.php';$('newPlanBtn').onclick=()=>newBlankPlan();$('savePlanBtn').onclick=savePlan;$('planSelect').onchange=e=>{if(e.target.value)loadPlan(e.target.value)};$('zoom').oninput=e=>{zoom=Number(e.target.value)/100;updateCanvas()};$('applyScaleBtn').onclick=()=>{const old=scale;planW=Math.max(10,Number($('planW').value)||50);planH=Math.max(10,Number($('planH').value)||34);scale=Math.max(8,Number($('scale').value)||24);const ratio=scale/old;stage.querySelectorAll('.structure').forEach(el=>{el.style.left=parseFloat(el.style.left)*ratio+'px';el.style.top=parseFloat(el.style.top)*ratio+'px';el.style.width=parseFloat(el.style.width)*ratio+'px';el.style.height=parseFloat(el.style.height)*ratio+'px';updateDim(el)});updateCanvas();stage.querySelectorAll('.equipment').forEach(el=>{const a=assetById(el.dataset.assetId),f=footprint(a);el.style.left=(a.xFt||0)*scale+'px';el.style.top=(a.yFt||0)*scale+'px';el.style.width=pxFromIn(f[0])+'px';el.style.height=pxFromIn(f[1])+'px'});dirty=true;recalc()};
document.querySelectorAll('[data-structure]').forEach(p=>{p.addEventListener('dragstart',e=>e.dataTransfer.setData('application/x-structure',p.dataset.structure));p.addEventListener('click',()=>{if(!CAN_EDIT)return;const el=makeStructure(p.dataset.structure,60,60);selectObject(el,'structure');dirty=true;recalc()})});stage.addEventListener('dragover',e=>{if(CAN_EDIT)e.preventDefault()});stage.addEventListener('drop',e=>{if(!CAN_EDIT)return;e.preventDefault();const r=stage.getBoundingClientRect(),x=(e.clientX-r.left)/zoom,y=(e.clientY-r.top)/zoom,assetId=e.dataTransfer.getData('application/x-equipment-asset'),type=e.dataTransfer.getData('application/x-structure');if(assetId)placeAsset(assetId,x/scale,y/scale);else if(type){const el=makeStructure(type,x,y);selectObject(el,'structure');dirty=true;recalc()}});stage.addEventListener('click',e=>{if(e.target===stage)selectObject(null,'')});
['sLabel','sW','sH','sSeats','sSeatZone'].forEach(id=>$(id).addEventListener('input',applyStructureInspector));$('assetSearch')?.addEventListener('input',renderCatalog);
$('deleteBtn').onclick=async()=>{if(!selected||!CAN_EDIT)return;if(selectedKind==='structure'){selected.remove();selectObject(null,'');dirty=true;recalc();return}const asset=assetById(selected.dataset.assetId);if(!asset||!confirm(`Remove ${asset.name} from this floor plan? The equipment record will remain in the catalog.`))return;try{const d=await api('api/equipment-placement.php',{method:'POST',body:{action:'unplace',assetId:asset.id}});Object.assign(asset,d.asset);selected.remove();selectObject(null,'');renderCatalog();recalc();setStatus('Equipment removed from plan')}catch(err){setStatus(err.message,true)}};
$('rotateBtn').onclick=async()=>{if(!selected||!CAN_EDIT)return;if(selectedKind==='structure'){const r=(Number(selected.dataset.rotation)||0)+90;selected.dataset.rotation=r%360;selected.style.transform=`rotate(${r%360}deg)`;dirty=true;return}const asset=assetById(selected.dataset.assetId);if(!asset||asset.locked)return;const rotation=((Number(asset.rotationDeg)||0)+90)%360;try{const d=await savePlacement(asset,'move',asset.xFt||0,asset.yFt||0,rotation,asset.zIndex||10);selected.dataset.rotation=d.rotationDeg;selected.style.transform=`rotate(${d.rotationDeg}deg)`;renderEquipmentInspector(d)}catch(err){setStatus(err.message,true)}};
$('frontBtn').onclick=async()=>{if(!selected||!CAN_EDIT)return;if(selectedKind==='structure'){selected.style.zIndex=++zCounter;dirty=true;return}const asset=assetById(selected.dataset.assetId);if(asset&&!asset.locked)await savePlacement(asset,'move',asset.xFt||0,asset.yFt||0,asset.rotationDeg||0,++zCounter);selected.style.zIndex=zCounter};
$('duplicateBtn').onclick=()=>{if(!selected||selectedKind!=='structure'||!CAN_EDIT)return;const d=structuralData(selected);d.id='';d.xPx+=scale;d.yPx+=scale;const el=makeStructure(d.type,d.xPx,d.yPx,d);selectObject(el,'structure');dirty=true;recalc()};
$('openAssetBtn').onclick=()=>selectedKind==='equipment'&&openAsset(assetById(selected.dataset.assetId));$('lockAssetBtn').onclick=async()=>{if(selectedKind!=='equipment'||!selected||!CAN_EDIT)return;const a=assetById(selected.dataset.assetId);try{const d=await api('api/equipment-placement.php',{method:'POST',body:{action:'lock',assetId:a.id,locked:!a.locked}});Object.assign(a,d.asset);selected.classList.toggle('locked',a.locked);renderEquipmentInspector(a);setStatus(a.locked?'Position locked':'Position unlocked')}catch(err){setStatus(err.message,true)}};
$('quickAssetBtn')?.addEventListener('click',()=>{$('assetModal').classList.add('open')});$('closeAssetModal')?.addEventListener('click',()=>{$('assetModal').classList.remove('open')});$('createAssetBtn')?.addEventListener('click',async()=>{const name=$('qaName').value.trim();if(!name)return setStatus('Equipment name is required.',true);try{const d=await api('api/equipment.php',{method:'POST',body:{action:'save_asset',asset:{name,assetType:$('qaType').value,purpose:$('qaPurpose').value.trim(),brand:$('qaBrand').value.trim(),model:$('qaModel').value.trim(),widthInches:$('qaWidth').value,depthInches:$('qaDepth').value,criticality:'medium',operationalStatus:'active',conditionStatus:'good'}}});$('assetModal').classList.remove('open');const newest=(d.assets||[]).find(a=>a.name===name)||null;await loadPlacements();setStatus('Equipment asset created');if(newest){$('assetSearch').value=name;renderCatalog()}}catch(err){setStatus(err.message,true)}});
$('agentAskBtn')?.addEventListener('click',()=>{askAgent($('agentInput').value);$('agentInput').value=''});$('agentInput')?.addEventListener('keydown',e=>{if(e.key==='Enter'){e.preventDefault();$('agentAskBtn').click()}});document.querySelectorAll('[data-agent-prompt]').forEach(b=>b.onclick=()=>askAgent(b.dataset.agentPrompt));$('askSelectedService')?.addEventListener('click',()=>{const a=selectedKind==='equipment'&&selected?assetById(selected.dataset.assetId):null;askAgent(a?`Who should I call to service ${a.name}?`:'Who are our equipment service contacts?')});
window.addEventListener('beforeunload',e=>{if(dirty){e.preventDefault();e.returnValue=''}})
}
bind();updateCanvas();listPlans().catch(err=>setStatus(err.message,true));
})();
</script>
</body>
</html>
